import {api,icon,esc,dateLabel,durationLabel,addDays,statusLabel,notify,whatsappUrl} from '/booking/shared.js';
const root=document.getElementById('booking-root');
const state={config:null,step:1,service:null,date:'',time:'',month:'',slots:[],loadingSlots:false,availabilityReason:'',availabilityError:false,name:'',phone:'',notes:'',consent:false,anamnesis:{chemicalHistory:'',chemicalDetails:'',allergies:'',allergyDetails:'',hairCare:'',consent:false},busy:false,error:'',idempotencyKey:crypto.randomUUID()};
let requestSequence=0;
async function init(){const receipt=new URL(location.href).searchParams.get('reserva');if(receipt){try{const booking=await api('/api/receipt/'+encodeURIComponent(receipt));return renderReceipt(booking);}catch(error){return renderProblem(error.message);}}try{state.config=await api('/api/config');if(!state.config.enabled)return renderClosed();state.month=state.config.today.slice(0,7);render();}catch(error){renderProblem(error.message);}}
function renderProblem(message){root.innerHTML=`<section class="closed-state"><div class="empty-icon">${icon('calendar')}</div><h1>Vamos tentar de novo?</h1><p>${esc(message)}</p><button class="btn" id="retry-booking">Tentar novamente ${icon('refresh')}</button><p style="margin-top:20px"><a href="/agendar/">Iniciar um novo agendamento</a></p></section>`;document.getElementById('retry-booking').onclick=init;}
function renderClosed(){root.innerHTML=`<section class="closed-state"><div class="empty-icon">${icon('flower')}</div><p class="label">SEU PRÓXIMO MOMENTO</p><h1>Estamos preparando<br>novos encontros de beleza.</h1><p>A agenda online ainda não está aberta. Enquanto isso, converse com o instituto pelo WhatsApp para consultar os atendimentos.</p><a class="btn" href="${whatsappUrl}" target="_blank" rel="noopener noreferrer">Conversar no WhatsApp ${icon('up')}</a></section>`;}
function render(){root.innerHTML=`<section class="client-intro"><p class="label">UM TEMPO SEU. UM CUIDADO ESPECIAL.</p><h1>Reserve o seu próximo<br><em>momento de beleza.</em></h1><p>Escolha seu cuidado, encontre um horário e deixe o resto com a gente.</p></section><div class="booking-layout"><section class="client-flow" aria-label="Agendamento"><nav class="steps" aria-label="Etapas do agendamento">${stepLabels()}</nav><div class="step-body" id="step-body"></div></section><aside class="summary-card" aria-label="Resumo do agendamento">${summary()}</aside></div>`;renderStep();}
function stepLabels(){return [[1,'Seu cuidado'],[2,'Seu momento'],[3,'Seus dados'],[4,'Anamnese']].map(([n,label],index)=>`${index?'<span class="step-line" aria-hidden="true"></span>':''}<div class="step-label ${state.step===n?'active':''} ${state.step>n?'done':''}" ${state.step===n?'aria-current="step"':''}><span>${state.step>n?icon('check'):'0'+n}</span>${label}</div>`).join('');}
function summary(){return `<div class="summary-photo"><img src="/assets/loiro-perolado.jpg" alt="Mechas loiras feitas no Babi Instituto"><span>BELEZA COM IDENTIDADE.<br>CUIDADO EM CADA DETALHE.</span>${icon('flower')}</div><div class="summary-body"><h2>Seu momento, em detalhes.</h2><div class="summary-row">${icon('flower')}<div><small>O cuidado escolhido</small><strong>${state.service?esc(state.service.name):'Ainda vamos escolher'}</strong></div></div><div class="summary-row">${icon('calendar')}<div><small>Dia e horário</small><strong>${state.date?esc(dateLabel(state.date,{day:'numeric',month:'long'})):'Escolha na próxima etapa'}${state.time?' · '+state.time:''}</strong></div></div><div class="summary-row">${icon('clock')}<div><small>Duração reservada</small><strong>${state.service?durationLabel(state.service.duration):'Depende do cuidado escolhido'}</strong></div></div><div class="summary-note"><span>${icon('shield')} Confirmação automática e segura</span>O horário fica reservado após a confirmação. Os valores do atendimento podem ser consultados diretamente com o instituto.</div></div>`;}
function updateSummary(){document.querySelector('.summary-card').innerHTML=summary();}
function renderStep(){const body=document.getElementById('step-body');state.error='';if(state.step===1){body.innerHTML=`<h2>Qual cuidado combina com você?</h2><p class="step-subtitle">Seu próximo capítulo começa por uma escolha.</p><div class="service-options" role="group" aria-label="Escolher serviço">${state.config.services.map(service=>`<button class="service-option ${state.service?.id===service.id?'selected':''}" data-service="${esc(service.id)}" aria-pressed="${state.service?.id===service.id}"><span class="service-symbol">${icon(service.id==='terapia'?'shield':service.id==='corte'?'flower':service.id==='cor'?'flower':'flower')}</span><div class="service-option-info"><strong>${esc(service.name)}</strong><p>${esc(service.description)}</p><small>${icon('clock').replace('<svg','<svg style="width:10px;height:10px;vertical-align:-2px;margin-right:4px"')} ${durationLabel(service.duration)}</small></div><span class="option-radio" aria-hidden="true"></span></button>`).join('')}</div><div class="step-actions"><span class="booking-progress-note">${icon('shield')} Sem pagamento nesta etapa</span><button class="btn" id="next-step" ${state.service?'':'disabled'}>Continuar ${icon('arrow')}</button></div>`;
body.querySelectorAll('[data-service]').forEach(button=>button.onclick=()=>{const service=state.config.services.find(s=>s.id===button.dataset.service);if(state.service?.id!==service.id){state.date='';state.time='';state.slots=[];state.idempotencyKey=crypto.randomUUID();}state.service=service;renderStep();updateSummary();});document.getElementById('next-step').onclick=()=>goStep(2);}
else if(state.step===2){body.innerHTML=`<h2>Quando é o seu momento?</h2><p class="step-subtitle">Os horários abaixo já consideram a duração do serviço escolhido.</p><div id="calendar"></div><div class="time-header">${icon('clock')}<span id="time-title">${state.date?esc(dateLabel(state.date,{weekday:'long',day:'numeric',month:'long'})):'Escolha um dia para ver os horários'}</span></div><div id="times-area" aria-live="polite"></div><div class="step-actions"><button class="step-back" id="previous-step">${icon('arrow')} Voltar</button><button class="btn" id="next-step" ${state.time?'':'disabled'}>Continuar ${icon('arrow')}</button></div><p class="booking-progress-note">${icon('clock')} Horários de Salvador / Bahia</p>`;renderCalendar();renderTimes();document.getElementById('previous-step').onclick=()=>goStep(1);document.getElementById('next-step').onclick=()=>goStep(3);}
else if(state.step===3){body.innerHTML=`<h2>Agora, um pouco sobre você.</h2><p class="step-subtitle">Seus dados para organizar o atendimento.</p><form class="details-form" id="customer-form"><label class="field">Seu nome completo<input name="name" autocomplete="name" minlength="3" maxlength="100" placeholder="Como podemos chamar você?" value="${esc(state.name)}" required></label><label class="field">Celular com DDD<input name="phone" type="tel" autocomplete="tel" inputmode="tel" minlength="10" maxlength="20" placeholder="(00) 00000-0000" value="${esc(state.phone)}" required><small>Um contato para falar com você sobre o atendimento.</small></label><label class="field">Observação sobre o agendamento (opcional)<textarea name="notes" maxlength="500" rows="3" placeholder="Uma referência ou pedido para o atendimento.">${esc(state.notes)}</textarea></label><label class="checkbox-label consent"><input type="checkbox" name="consent" ${state.consent?'checked':''} required>Autorizo o uso do meu nome, contato e observação para organizar este agendamento.</label><p id="customer-error" class="form-error" role="alert"></p><div class="step-actions"><button type="button" class="step-back" id="previous-step">${icon('arrow')} Voltar</button><button class="btn" type="submit">Continuar ${icon('arrow')}</button></div></form>`;
const form=document.getElementById('customer-form');const capture=()=>{const data=new FormData(form);state.name=String(data.get('name')||'');state.phone=String(data.get('phone')||'');state.notes=String(data.get('notes')||'');state.consent=data.has('consent');};form.oninput=capture;form.onsubmit=event=>{event.preventDefault();capture();const phone=state.phone.replace(/\D/g,'');if(phone.length<10||phone.length>13){document.getElementById('customer-error').textContent='Informe um telefone válido com DDD.';return;}goStep(4);};document.getElementById('previous-step').onclick=()=>goStep(2);}
else renderAnamnesis(body);}
function renderAnamnesis(body){const a=state.anamnesis;const options=value=>[['','Selecione uma resposta'],['no','Não'],['yes','Sim'],['unsure','Não sei informar'],['private','Prefiro conversar pessoalmente']].map(([key,label])=>`<option value="${key}" ${value===key?'selected':''}>${label}</option>`).join('');
body.innerHTML=`<h2>Um cuidado que começa na escuta.</h2><p class="step-subtitle">Anamnese capilar: conte o que ajuda a preparar o seu atendimento. Você pode preferir conversar pessoalmente.</p><form id="anamnesis-form" class="details-form"><fieldset class="intake-group"><legend>Histórico dos fios</legend><label class="field">Já fez química nos cabelos?<select name="chemicalHistory" required>${options(a.chemicalHistory)}</select></label><label class="field" id="chemical-details" ${a.chemicalHistory==='yes'?'':'hidden'}>Quais procedimentos e quando? (opcional)<textarea name="chemicalDetails" rows="3" maxlength="500" placeholder="Ex.: coloração, mechas, alisamento e a época aproximada.">${esc(a.chemicalDetails)}</textarea></label></fieldset><fieldset class="intake-group"><legend>Reações a produtos</legend><label class="field">Tem alergias ou já teve reação a produtos capilares?<select name="allergies" required>${options(a.allergies)}</select></label><label class="field" id="allergy-details" ${a.allergies==='yes'?'':'hidden'}>O que você gostaria de informar? (opcional)<textarea name="allergyDetails" rows="3" maxlength="500" placeholder="Informe o produto ou a reação, se desejar.">${esc(a.allergyDetails)}</textarea></label></fieldset><label class="field">Cuidados e observações sobre seus fios (opcional)<textarea name="hairCare" maxlength="500" rows="3" placeholder="Conte sobre sua rotina ou algo que gostaria de conversar no atendimento.">${esc(a.hairCare)}</textarea></label><div class="intake-privacy">${icon('shield')}<p>Estas respostas ficam nos detalhes privados do seu atendimento. Elas não aparecem no comprovante público da reserva. Compartilhe apenas o que considerar necessário.</p></div><label class="checkbox-label consent"><input type="checkbox" name="anamnesisConsent" ${a.consent?'checked':''} required>Autorizo o Babi Instituto a armazenar e consultar minhas respostas, inclusive informações sobre alergias e reações que eu escolher fornecer, para preparar e realizar meu atendimento.</label><div id="booking-error" role="alert"></div><div class="step-actions"><button type="button" class="step-back" id="previous-step">${icon('arrow')} Voltar</button><button class="btn" id="confirm-booking" type="submit">Confirmar meu horário ${icon('check')}</button></div><p class="booking-progress-note">${icon('shield')} A confirmação aparece após salvar sua reserva.</p></form>`;
const form=document.getElementById('anamnesis-form');form.oninput=()=>{const data=new FormData(form);for(const key of ['chemicalHistory','chemicalDetails','allergies','allergyDetails','hairCare'])a[key]=String(data.get(key)||'');a.consent=data.has('anamnesisConsent');document.getElementById('chemical-details').hidden=a.chemicalHistory!=='yes';document.getElementById('allergy-details').hidden=a.allergies!=='yes';};form.onsubmit=submitBooking;document.getElementById('previous-step').onclick=()=>goStep(3);}

function goStep(step){state.step=step;render();document.querySelector('.client-flow').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'start'});const heading=document.querySelector('.step-body>h2');heading.setAttribute('tabindex','-1');heading.focus({preventScroll:true});if(step===2&&state.date)fetchTimes();}
function renderCalendar(){const first=state.month+'-01',start=new Date(first+'T12:00:00Z').getUTCDay(),last=addDays(addDays(first,32).slice(0,7)+'-01',-1),total=Number(last.slice(-2));const previous=new Date(first+'T12:00:00Z');previous.setUTCMonth(previous.getUTCMonth()-1);const prevMonth=previous.toISOString().slice(0,7);const next=addDays(first,32).slice(0,7);
document.getElementById('calendar').innerHTML=`<div class="month-header"><h3>${esc(dateLabel(first,{month:'long',year:'numeric'}))}</h3><div class="month-arrows"><button class="icon-btn previous" id="previous-month" aria-label="Mês anterior" ${prevMonth<state.config.today.slice(0,7)?'disabled':''}>${icon('chevron')}</button><button class="icon-btn" id="next-month" aria-label="Próximo mês" ${next>state.config.maxDate.slice(0,7)?'disabled':''}>${icon('chevron')}</button></div></div><div class="calendar-grid" role="group" aria-label="Escolher dia">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(day=>`<span class="calendar-weekday">${day}</span>`).join('')}${'<span aria-hidden="true"></span>'.repeat(start)}${Array.from({length:total},(_,index)=>{const date=`${state.month}-${String(index+1).padStart(2,'0')}`,disabled=date<state.config.today||date>state.config.maxDate;return `<button class="calendar-date ${date===state.date?'selected':''} ${date===state.config.today?'today':''}" data-date="${date}" aria-label="${esc(dateLabel(date,{weekday:'long',day:'numeric',month:'long'}))}" aria-pressed="${date===state.date}" ${disabled?'disabled':''}>${index+1}</button>`;}).join('')}</div>`;
document.getElementById('previous-month').onclick=()=>{state.month=prevMonth;renderCalendar();};document.getElementById('next-month').onclick=()=>{state.month=next;renderCalendar();};document.querySelectorAll('[data-date]').forEach(button=>button.onclick=()=>{state.date=button.dataset.date;state.time='';state.idempotencyKey=crypto.randomUUID();renderCalendar();updateSummary();fetchTimes();});}
async function fetchTimes(){const sequence=++requestSequence;state.loadingSlots=true;state.availabilityError=false;renderTimes();document.getElementById('next-step').disabled=true;document.getElementById('time-title').textContent=dateLabel(state.date,{weekday:'long',day:'numeric',month:'long'});try{const result=await api(`/api/availability?date=${state.date}&service=${encodeURIComponent(state.service.id)}`);if(sequence!==requestSequence||state.step!==2)return;state.slots=result.slots;state.availabilityReason=result.reason;if(state.time&&!state.slots.includes(state.time))state.time='';}catch(error){if(sequence!==requestSequence||state.step!==2)return;state.slots=[];state.availabilityReason=error.message;state.availabilityError=true;state.time='';}finally{if(sequence===requestSequence&&state.step===2){state.loadingSlots=false;renderTimes();updateSummary();document.getElementById('next-step').disabled=!state.time;}}}
function renderTimes(){const area=document.getElementById('times-area');if(state.loadingSlots){area.innerHTML='<div class="calendar-loading"><span class="loader"></span>Consultando horários disponíveis...</div>';return;}if(!state.date){area.innerHTML='<p class="time-message">Toque em uma data no calendário para encontrar seu horário.</p>';return;}if(!state.slots.length){area.innerHTML=`<p class="time-message">${esc(state.availabilityReason||'Nenhum horário disponível. Escolha outra data.')}</p>${state.availabilityError?'<button class="btn btn-secondary" id="retry-times">Tentar novamente</button>':''}`;document.getElementById('retry-times')?.addEventListener('click',fetchTimes);return;}area.innerHTML=`<div class="time-slots" role="group" aria-label="Horários disponíveis">${state.slots.map(time=>`<button class="time-option ${state.time===time?'selected':''}" data-time="${time}" aria-pressed="${state.time===time}">${time}</button>`).join('')}</div>`;area.querySelectorAll('[data-time]').forEach(button=>button.onclick=()=>{state.time=button.dataset.time;state.idempotencyKey=crypto.randomUUID();renderTimes();updateSummary();document.getElementById('next-step').disabled=false;});}
async function submitBooking(event){event.preventDefault();if(state.busy)return;event.currentTarget.oninput();const phone=state.phone.replace(/\D/g,'');if(phone.length<10||phone.length>13){document.getElementById('booking-error').innerHTML='<p class="inline-error">Informe um telefone válido com DDD.</p>';return;}state.busy=true;const button=document.getElementById('confirm-booking');button.disabled=true;button.innerHTML='Reservando seu momento...';document.getElementById('previous-step').disabled=true;document.getElementById('booking-error').innerHTML='';try{const booking=await api('/api/bookings',{method:'POST',body:JSON.stringify({serviceId:state.service.id,date:state.date,time:state.time,name:state.name,phone:state.phone,notes:state.notes,consent:state.consent,anamnesis:state.anamnesis,idempotencyKey:state.idempotencyKey})});history.replaceState(null,'',`/agendar/?reserva=${booking.token}`);renderReceipt(booking);window.scrollTo({top:0,behavior:'smooth'});}catch(error){if(error.status===409){state.time='';state.idempotencyKey=crypto.randomUUID();goStep(2);notify(error.message,true);}else{document.getElementById('booking-error').innerHTML=`<p class="inline-error">${esc(error.message)}</p>`;button.disabled=false;button.innerHTML='Confirmar meu horário '+icon('check');document.getElementById('previous-step').disabled=false;}}finally{state.busy=false;}}
function renderReceipt(booking){
 const cancelled=booking.status==='cancelled',completed=booking.status==='completed';
 const payments={pending:'A realizar no atendimento',received:'Recebido',courtesy:'Cortesia',unrecorded:'Recebimento não informado',not_applicable:'Não se aplica'};
 const payment=Object.hasOwn(payments,booking.paymentStatus)?booking.paymentStatus:'pending';
 const message=cancelled?'Esse horário foi liberado na agenda. Você pode escolher um novo momento.':completed?'Seu atendimento foi concluído.': 'Seu horário foi confirmado. O pagamento é realizado no atendimento.';
 root.innerHTML=`<article class="receipt-card"><header class="receipt-top"><div class="receipt-check">${icon(cancelled?'close':'check')}</div><p class="label">${cancelled?'RESERVA CANCELADA':completed?'ATENDIMENTO CONCLUÍDO':'AGENDAMENTO CONFIRMADO'}</p><h1>${cancelled?'Seu agendamento foi cancelado.':completed?'Seu cuidado, registrado.':`${esc(booking.name)}, esperamos por você.`}</h1><p>${message}</p></header><div class="receipt-body"><dl class="detail-grid"><div><dt>Seu cuidado</dt><dd>${esc(booking.service)}</dd></div><div><dt>Agendamento</dt><dd><span class="status ${booking.status}">${statusLabel[booking.status]}</span></dd></div><div><dt>Data</dt><dd>${esc(dateLabel(booking.date,{weekday:'long',day:'numeric',month:'long'}))}</dd></div><div><dt>Horário e duração</dt><dd>${esc(booking.time)} · ${durationLabel(booking.duration)}</dd></div></dl><div class="receipt-payment"><span>Pagamento</span><strong class="payment-status payment-${payment}">${payments[payment]}</strong><p>${payment==='pending'?'O site reserva o horário. Combine os detalhes do pagamento com o instituto.':payment==='received'?'Recebimento registrado pelo instituto.':payment==='courtesy'?'Atendimento registrado como cortesia pelo instituto.':payment==='unrecorded'?'O instituto ainda não informou o recebimento deste atendimento.':'Não há recebimento associado a esta reserva cancelada.'}</p></div><div class="receipt-code"><span>Código do agendamento</span><strong>${esc(booking.code)}</strong></div><p class="summary-note">Guarde o link desta página para consultar sua reserva. Para reagendar, cancelar ou consultar os valores e o local de atendimento, <a href="${whatsappUrl}" target="_blank" rel="noopener noreferrer">fale com o instituto pelo WhatsApp</a>. Não há cobrança ou envio automático de mensagem por esta página.</p><div class="receipt-actions"><button class="btn" id="copy-receipt">Copiar link da reserva ${icon('check')}</button><a class="btn btn-secondary" href="/">Voltar ao site ${icon('arrow')}</a></div></div></article>`;
 document.getElementById('copy-receipt').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);notify('Link da reserva copiado. Guarde-o com você.');}catch{notify('Copie o endereço desta página na barra do navegador.');}};
}

init();
